// SessionServiceHandler is an implementation of the aide.session.v1.SessionService service.
type SessionServiceHandler interface {
	StartSession(context.Context, *v1.StartSessionRequest) (*v1.StartSessionResponse, error)
	GetSession(context.Context, *v1.GetSessionRequest) (*v1.Session, error)
	ListSessions(context.Context, *v1.ListSessionsRequest) (*v1.ListSessionsResponse, error)
	// WatchSessions sends the sessions the caller can read as they change:
	// first an empty message once the watch is in place, then the sessions
	// started or changed since the last message, each as it is now (changes
	// that come close together are sent together).
	WatchSessions(context.Context, *v1.WatchSessionsRequest, *connect.ServerStream[v1.WatchSessionsResponse]) error
	StreamEvents(context.Context, *v1.StreamEventsRequest, *connect.ServerStream[v1.SessionEvent]) error
	// ListEvents returns one page of a session's events, oldest first.
	ListEvents(context.Context, *v1.ListEventsRequest) (*v1.ListEventsResponse, error)
	SendMessage(context.Context, *v1.SendMessageRequest) (*v1.SendMessageResponse, error)
	// DeliverMessage hands the session a message an agent wrote, signed by
	// that agent (docs/agent-messages.md §7): it joins its sender's own turn,
	// answers its sender's own question, or starts, or waits for, a turn of
	// its own. Any agent whose grant covers the session and that may read it
	// can deliver one.
	DeliverMessage(context.Context, *v1.DeliverMessageRequest) (*v1.DeliverMessageResponse, error)
	// InterruptSession stops the turn in progress; the session stays, idle,
	// and the next message goes on in the same agent conversation.
	InterruptSession(context.Context, *v1.InterruptSessionRequest) (*v1.Session, error)
	// ArchiveSession makes an idle session read-only and frees its worktree
	// (its branch keeps the work). Sessions never end otherwise.
	ArchiveSession(context.Context, *v1.ArchiveSessionRequest) (*v1.Session, error)
	// UnarchiveSession restores the worktree from the branch; the session is
	// idle again.
	UnarchiveSession(context.Context, *v1.UnarchiveSessionRequest) (*v1.Session, error)
	// DeleteSession deletes a session for good: its record, events,
	// attachments and worktree. Its branch stays in the project, with every
	// turn's work, and its tokens stay in GetUsage. A turn in progress is
	// interrupted first. Only the owner's devices may delete.
	DeleteSession(context.Context, *v1.DeleteSessionRequest) (*v1.DeleteSessionResponse, error)
	// RenameSession changes the session's title. Only the owner's devices
	// may rename.
	RenameSession(context.Context, *v1.RenameSessionRequest) (*v1.Session, error)
	GetDiff(context.Context, *v1.GetDiffRequest) (*v1.GetDiffResponse, error)
	// AnswerQuestion answers (or declines) a question the agent asked.
	AnswerQuestion(context.Context, *v1.AnswerQuestionRequest) (*v1.Session, error)
	// ReadToolOutput streams a tool's whole output, as recorded (up to 1 MiB;
	// past that its first and last 512 KiB), in chunks of at most 64 KiB:
	// what a BASIC event's preview, or a FULL one's first 16 KiB, is part of.
	ReadToolOutput(context.Context, *v1.ReadToolOutputRequest, *connect.ServerStream[v1.ToolOutputChunk]) error
	// PushSession pushes the session's branch, as its last finished turn
	// left it, to its repository's remote origin under the same name, with
	// the machine's own git credentials (never forced). Aide never pushes
	// otherwise: only the owner or the client that started the session asks.
	PushSession(context.Context, *v1.PushSessionRequest) (*v1.PushSessionResponse, error)
	// RollbackSession puts an idle (or crashed) worktree session back to
	// where an earlier turn left it: its worktree and branch are reset to
	// that turn's snapshot commit, the later turns' conversation and changes
	// are discarded, and the next message starts a fresh agent conversation
	// that is told so. The discarded turns stay in the timeline, after them
	// a RolledBack event. In-place sessions have no snapshots and are
	// refused (FAILED_PRECONDITION), as is a session with a turn running.
	RollbackSession(context.Context, *v1.RollbackSessionRequest) (*v1.Session, error)
	// ListCheckpoints returns the per-turn workspace checkpoints stored under
	// hidden git refs (refs/aide/checkpoints/<session_id>/turn-<N>), along with
	// non-git/in-place status, conversation rollback capability, and retention
	// policy (工单 #113).
	ListCheckpoints(context.Context, *v1.ListCheckpointsRequest) (*v1.ListCheckpointsResponse, error)
	// ClearCheckpoints manually removes hidden git ref checkpoints for a session
	// (optionally keeping keep_latest most recent entries; 0 removes all).
	ClearCheckpoints(context.Context, *v1.ClearCheckpointsRequest) (*v1.ClearCheckpointsResponse, error)
	// MarkSessionSeen records what the owner has seen of the session
	// (Session.seen), on its machine, so every device of the owner agrees.
	// Only the owner's devices may mark. It is not activity: updated_at
	// stays (lists keep their order); nothing is written when nothing new is
	// seen, nor of an archived session.
	MarkSessionSeen(context.Context, *v1.MarkSessionSeenRequest) (*v1.Session, error)
	// GetSessionInsights reviews a session from its stored events
	// (docs/session-insights.md): each turn's time, failures and retries,
	// stalls and interrupts, questions and how long they waited, tool calls,
	// changes and tokens, what the review finds, and a better prompt to
	// dispatch such work with. Worked out by rules, never by a model; made
	// when the session is archived or when asked, and kept until a new event
	// comes.
	GetSessionInsights(context.Context, *v1.GetSessionInsightsRequest) (*v1.SessionInsights, error)
	// ReadAttachment gives back a file the session keeps (工单 #156), so that
	// any device shows it, after a restart too: a file a user message
	// attached, or a picture a reply of the agent's showed and its turn kept
	// (TurnCompleted.shown, 工单 #158), found by its SHA-256. Never any other
	// file. By path, for a picture a reply showed that no turn kept (the turn
	// is still running, or ended before pictures were kept): the owner only,
	// and only a picture (PNG, JPEG, GIF or WebP by its content, at most
	// 10 MiB) that a reply in this session showed.
	ReadAttachment(context.Context, *v1.ReadAttachmentRequest) (*v1.ReadAttachmentResponse, error)
}

